{"path":"/app/maximal_square.py","content":""""Fast CPU implementation of maximal square for NumPy arrays.

The public API intentionally matches the reference implementation:

    maximal_square(matrix: np.ndarray) -> int

For large inputs this module uses a small C backend compiled on first import and
called through ctypes.  The one-time compilation cost is acceptable for long
runs; the actual computation is the same dynamic-programming recurrence as the
reference code, but executed in native code instead of Python loops.
"""

import ctypes
import hashlib
import os
import subprocess
import tempfile

import numpy as np


_C_SOURCE = r'''
#include <stdint.h>
#include <stdlib.h>

#if defined(_WIN32)
#  define EXPORT __declspec(dllexport)
#else
#  define EXPORT __attribute__((visibility("default")))
#endif

static inline int min3_int(int a, int b, int c) {
    int m = a < b ? a : b;
    return m < c ? m : c;
}

EXPORT long long maximal_square_u8(const uint8_t *data, long long rows, long long cols) {
    if (data == NULL || rows <= 0 || cols <= 0) return 0;

    int *dp = (int *)calloc((size_t)cols + 1u, sizeof(int));
    if (dp == NULL) return -1;

    int maxsqlen = 0;
    for (long long i = 0; i < rows; ++i) {
        int prev = 0;
        const uint8_t *row = data + i * cols;
        for (long long j = 1; j <= cols; ++j) {
            int temp = dp[j];
            if (row[j - 1] != 0) {
                int v = min3_int(dp[j - 1], prev, dp[j]) + 1;
                dp[j] = v;
                if (v > maxsqlen) maxsqlen = v;
            } else {
                dp[j] = 0;
            }
            prev = temp;
        }
    }

    free(dp);
    return (long long)maxsqlen * (long long)maxsqlen;
}
'''


_LIB = None
_COMPILE_ERROR = None


def _compile_and_load_backend():
    """Build and load the tiny C backend, caching it in the temp directory."""
    global _COMPILE_ERROR

    key = hashlib.sha256(_C_SOURCE.encode("utf-8")).hexdigest()[:16]
    build_dir = os.path.join(tempfile.gettempdir(), "maximal_square_c_backend")
    src_path = os.path.join(build_dir, "maximal_square_%s.c" % key)
    so_path = os.path.join(build_dir, "maximal_square_%s.so" % key)

    try:
        if not os.path.isdir(build_dir):
            os.makedirs(build_dir)
        if not os.path.exists(so_path):
            with open(src_path, "w") as f:
                f.write(_C_SOURCE)
            cmd = [
                "gcc", "-O3", "-march=native", "-std=c99", "-shared", "-fPIC",
                src_path, "-o", so_path,
            ]
            subprocess.check_call(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

        lib = ctypes.CDLL(so_path)
        func = lib.maximal_square_u8
        func.argtypes = [
            ctypes.POINTER(ctypes.c_uint8),
            ctypes.c_longlong,
            ctypes.c_longlong,
        ]
        func.restype = ctypes.c_longlong
        return lib
    except Exception as exc:  # pragma: no cover - fallback path is environment dependent
        _COMPILE_ERROR = exc
        return None


def _python_fallback(matrix):
    """Reference-equivalent fallback used only if a C compiler is unavailable."""
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    dp = [0] * (cols + 1)
    maxsqlen = 0
    for i in range(1, rows + 1):
        prev = 0
        for j in range(1, cols + 1):
            temp = dp[j]
            if matrix[i - 1, j - 1] == 1:
                v = min(dp[j - 1], prev, dp[j]) + 1
                dp[j] = v
                if v > maxsqlen:
                    maxsqlen = v
            else:
                dp[j] = 0
            prev = temp
    return maxsqlen * maxsqlen


def maximal_square(matrix: np.ndarray) -> int:
    """Return the area of the largest all-1 square in a binary NumPy array.

    Parameters
    ----------
    matrix : np.ndarray
        Two-dimensional array containing only 0s and 1s.  Non-zero values are
        treated as 1 by the accelerated backend, which is equivalent for valid
        binary inputs.

    Returns
    -------
    int
        Area of the largest square containing only 1s.
    """
    arr = np.asarray(matrix)
    if arr.ndim != 2:
        raise ValueError("matrix must be a 2-dimensional numpy ndarray")

    rows, cols = arr.shape
    if rows == 0 or cols == 0:
        return 0

    # The C kernel is specialized for dense uint8 row-major input.  For the
    # expected large binary matrices this copy/conversion is tiny compared with
    # eliminating ~1,000,000 Python-loop iterations per call.
    arr_u8 = np.ascontiguousarray(arr, dtype=np.uint8)

    global _LIB
    if _LIB is None:
        _LIB = _compile_and_load_backend()

    if _LIB is not None:
        ptr = arr_u8.ctypes.data_as(ctypes.POINTER(ctypes.c_uint8))
        result = _LIB.maximal_square_u8(ptr, int(rows), int(cols))
        if result >= 0:
            return int(result)
        # Allocation failure inside the C routine is very unlikely; fall back to
        # the Python implementation rather than returning an invalid value.

    return int(_python_fallback(arr_u8))


__all__ = ["maximal_square"]
